# term (regex, case-insensitive, matches word stems) -> definition
GLOSSARY = [
 (r"однонуклеотидн\w+ вариант\w*", "Однонуклеотидный вариант (SNV)", "Замена одной «буквы» ДНК на другую в определённой позиции. Самый частый тип различий между людьми."),
 (r"экзон\w*", "Экзон", "Кусок гена, который попадает в готовую РНК и кодирует белок. Между экзонами — интроны, которые вырезаются."),
 (r"интрон\w*", "Интрон", "Участок гена, который вырезается из РНК до сборки белка. Белок не кодирует, но часто содержит переключатели."),
 (r"энхансер\w*", "Энхансер", "Регуляторный участок ДНК-«усилитель»: белки-регуляторы садятся на него и включают ген, иногда за десятки тысяч букв от него."),
 (r"промотор\w+", "Промотор", "Участок перед геном, с которого начинается считывание. Опечатка здесь меняет «громкость» гена."),
 (r"миссенс\w*", "Миссенс", "Замена, которая меняет одну аминокислоту в белке. Белок собирается, но с другой «деталью»."),
 (r"нонсенс\w*|стоп-сигнал\w*|стоп-кодон\w*", "Нонсенс (стоп-кодон)", "Замена, превращающая код аминокислоты в сигнал «стоп». Сборка белка обрывается раньше времени."),
 (r"сплайсинг\w*|нарезк\w+ РНК|нарезается РНК", "Сплайсинг", "«Нарезка» РНК: вырезание интронов и склейка экзонов. Опечатка на границе экзона сбивает нарезку."),
 (r"экспресси\w+", "Экспрессия", "Насколько активно ген считывается, то есть сколько с него делают РНК и белка. Здесь — «громкость гена»."),
 (r"белк\w+-регулятор\w*|транскрипционн\w+ фактор\w*|связывание ТФ", "Белок-регулятор (транскрипционный фактор)", "Белок, который узнаёт короткий мотив в ДНК, садится на него и включает или выключает соседние гены."),
 (r"аминокислот\w+", "Аминокислота", "«Бусина» белка. Белок — цепочка из аминокислот, порядок которых записан в гене тройками букв."),
 (r"\bфермент\w*", "Фермент", "Белок-катализатор: ускоряет одну конкретную химическую реакцию, например расщепление кофеина или лактозы."),
 (r"естественн\w+ отбор\w*|\bотбор\w*", "Естественный отбор", "Если вариант гена помогает выживать и оставлять потомство, за поколения он становится частым в популяции."),
 (r"\bкопи[яию]\w*", "Копия гена (аллель)", "У каждого гена две копии — от матери и от отца. Признак может зависеть от одной сломанной копии или требовать двух."),
 (r"GWAS", "GWAS", "Полногеномный поиск ассоциаций: сравнение ДНК тысяч людей с признаком и без, чтобы найти связанные с ним варианты."),
 (r"AVI", "AVI", "AlphaGenome Variant Impact — сводная оценка Атласа, насколько замена меняет молекулярную работу участка. Не «вредность для здоровья»."),
 (r"AlphaMissense", "AlphaMissense", "Модель DeepMind (2023), предсказывающая, насколько замена аминокислоты ломает белок. Дополняет AlphaGenome для кодирующих участков."),
 (r"меланин\w*|меланоцит\w*", "Меланин", "Пигмент кожи, волос и радужки. Делают его клетки-меланоциты; тёмный эумеланин и красно-жёлтый феомеланин."),
 (r"антиген\w+", "Антиген", "Молекула на поверхности клетки, по которой её узнают — иммунная система или вирус. Антигены групп крови — из этого ряда."),
 (r"микрофлор\w+|микробиот\w+", "Микрофлора (микробиота)", "Сообщество бактерий в кишечнике. Его состав зависит и от питания, и от генов хозяина."),
 (r"hg38|GRCh38", "hg38 (GRCh38)", "Версия «эталонного» генома человека, относительно которой указывают координаты вариантов."),
 (r"rs\d{3,}", "rsID", "Номер варианта в базе dbSNP — универсальный «паспорт» замены, по которому её можно найти в любой базе."),
 (r"кодирующ\w+ участ\w+|кодирующ\w+ част\w+", "Кодирующий участок", "Часть гена, буквы которой тройками переводятся в аминокислоты белка. Всего около 1–2 % генома."),
]

# Абзац «Что видит модель» — по реальным данным Atlas (окно ±5 000 букв, 30 000 замен на ген)
MODEL = {
 'LCT': "Модель ставит варианту AVI 0,29 — квантиль 0,96, то есть сильнее 96 % всех замен генома, но далеко не рекорд: 7 % соседних замен в окне бьют его. Зато механизм угадан точно: оценка почти целиком сложена из «открытости хроматина» и старта транскрипции — так выглядит энхансер, — а самый сильный сдвиг экспрессии LCT предсказан в слизистой толстой и тонкой кишки, хотя модели никто не говорил, что это «ген молока».",
 'CYP1A2': "А вот здесь модель говорит неожиданное. AVI знаменитого варианта — минус 0,29, квантиль 0,003: по оценке Atlas это одна из самых безобидных замен во всём геноме, слабее 99 % соседей. Сдвиг экспрессии CYP1A2 — крошечный и не в печени, а в жировой ткани и эпителии молочной железы. Это не значит, что «ген кофе» — выдумка: связь варианта со скоростью метаболизма кофеина многократно воспроизведена. Объяснения два, и честно назвать оба. Либо механизм не в этой букве — rs762551 просто наследуется вместе с настоящей причиной, которую ещё предстоит найти. Либо это ровно тот класс тихих регуляторных сдвигов, на которых такие модели документированно спотыкаются: предсказывать разницу экспрессии между людьми AlphaGenome умеет заметно хуже всего остального. Самая честная глава в этой истории.",
 'ALDH2': "Здесь всё громко: AVI 1,47, квантиль 0,999, сильнее 99,5 % соседних замен. Оценка поровну сложена из AlphaMissense — «эта аминокислота ломает белок» — и эволюционной консервативности: за сотни миллионов лет эту букву не трогал никто. При этом экспрессия ALDH2 по тканям почти не меняется (сдвиги в тысячных долях), и это правильно: ген читается как обычно, негодной получается сама деталь.",
 'ACTN3': "AVI 1,55, квантиль 0,999; 88 % оценки — признак «обрыв белка». Заметьте окно вокруг варианта: 17 % всех замен в нём попадают в верхний процент генома — рекорд среди наших десяти. Причина проста: ACTN3 плотно нарезан на экзоны, и почти каждая буква здесь что-то кодирует. А самые сильные, пусть и небольшие, сдвиги экспрессии модель предсказала в икроножной и поясничной мышцах и в миобластах — то есть ровно там, где ген и работает.",
 'HERC2': "Скромно: AVI 0,34, квантиль 0,97, 8 % соседей сильнее. Оценка на 90 % сложена из консервативности — «эту букву берегут», — но предсказанный сдвиг экспрессии OCA2 в доступных моделью тканях почти нулевой. Тут стоит быть честными: эффект этого энхансера показан в меланоцитах через дальнодействующую петлю ДНК, а среди 371 трека модели меланоцитов радужки нет. Модель видит, что место важное, но не может показать, чем именно — хороший пример границ метода.",
 'TAS2R38': "AVI 0,40, квантиль 0,98. Любопытно, что доминирует не AlphaMissense (всего 10 %), а консервативность: замена аминокислоты сама по себе не выглядит разрушительной — что согласуется с тем, что обе версии рецептора нормально работают, просто по-разному. А самый сильный сдвиг экспрессии TAS2R38 модель нашла не на языке, а в клетках крови — NK-клетках и B-лимфоцитах. Это не ошибка: рецепторы горького вкуса действительно есть у иммунных клеток, и там они «пробуют» бактерии.",
 'MC1R': "AVI 0,55, квантиль 0,99: заметно, но не катастрофично — 5 % соседей сильнее. Консервативность даёт 69 % оценки, AlphaMissense — 25 %. Экспрессия не меняется, что ожидаемо для миссенс-замены. Ироничная деталь: среди 371 трека модели нет меланоцитов волосяного фолликула, так что «ген рыжих» она оценивает по общим признакам — и всё равно ставит его в верхний процент.",
 'ABCC11': "AVI 1,35, квантиль 0,998, сильнее 99,8 % соседних замен — при том что окно вокруг варианта самое «спокойное» из десяти, всего 1,8 % замен в верхнем проценте. Половина оценки — AlphaMissense, половина — консервативность. Единственный ощутимый сдвиг экспрессии, и тот отрицательный и небольшой, модель предсказала в печени — там ABCC11 тоже работает, хотя историю с потом и ушной серой из этого не вычитать.",
 'OR6A2': "Самая тихая замена из десяти после «гена кофе»: AVI 0,06, квантиль 0,77 — обычнее, чем каждая пятая замена в окне. Сдвиги экспрессии — в тысячных долях, в случайных клеточных линиях. Модель почти ничего не видит, и это согласуется с генетикой: вариант объясняет меньше процента разницы в восприятии кинзы, а его механизм не установлен. Хорошее напоминание, что «ген кинзы» — скорее заголовок, чем ген.",
 'FUT2': "Абсолютный чемпион: AVI 2,11, квантиль 0,9997, сильнее всех 30 000 соседних замен без исключения. Семьдесят процентов оценки — «обрыв белка», остальное — консервативность. И здесь модель показала кое-что тонкое: предсказанное падение экспрессии FUT2 сильнее всего в эпителии трахеи, носа и бронхов — на тех самых слизистых, где секреторы выставляют антигены. Клетка распознаёт РНК со стоп-сигналом посреди инструкции и уничтожает её, и модель это знает.",
}
